@if($canCount)<script>document.querySelectorAll('.sc-count-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button'),label=button.querySelector('span'),old=label.textContent;button.disabled=true;label.textContent='Saving…';try{const res=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await res.json();if(!res.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||data.message);document.querySelectorAll('[data-progress]').forEach(el=>el.textContent=data.counted+' / '+data.total);document.querySelectorAll('[data-progress-bar]').forEach(el=>el.style.width=(data.total?data.counted/data.total*100:0)+'%');button.classList.remove('btn-outline-primary');button.classList.add('btn-light');label.textContent='Saved ✓';setTimeout(()=>label.textContent='Update',1200)}catch(err){alert(err.message);label.textContent=old}finally{button.disabled=false}}));</script>@endif
@if(!$canCount && in_array($task->status,['scheduled','in_progress']) && auth()->user()->hasAdminPermission('stock-counts.view'))<script>setTimeout(()=>location.reload(),30000);</script>@endif
